<?php
require __DIR__.'/app/bootstrap.php';$u=require_user(false);require_commerce();$type=param('type')==='food'?'food':'shops';$title=$type==='shops'?t('Favourite shops'):t('Favourite food');
if($type==='shops')$saved=all("SELECT f.*,s.id store_id,s.status,s.business_name,s.address,s.logo_id FROM favourite_shops f LEFT JOIN seller_applications s ON s.user_id=f.seller_id WHERE f.user_id=? ORDER BY f.created_at DESC",[$u['id']]);
else $saved=all("SELECT f.*,m.name,m.price_paisa,m.photo_id,m.expires_at,m.status menu_status,c.active category_active,s.id store_id,s.status shop_status,s.business_name FROM favourite_food f LEFT JOIN menu_items m ON m.id=f.product_id LEFT JOIN categories c ON c.id=m.category_id LEFT JOIN seller_applications s ON s.user_id=f.seller_id WHERE f.user_id=? ORDER BY f.created_at DESC",[$u['id']]);
require ROOT.'/app/header.php'; ?>
<main class="page shell" id="main"><div class="page-heading"><span class="heading-kicker"><?=e(t('A FEW THINGS YOU LOVE'))?></span><h1><?=e($title)?></h1><p><?=e(t('Keep your favourite kitchens and dishes close.'))?></p></div><nav class="tabs"><a class="pill <?=$type==='shops'?'primary':''?>" href="<?=e(url('favourites.php?type=shops'))?>"><?=e(t('Favourite Shops'))?></a><a class="pill <?=$type==='food'?'primary':''?>" href="<?=e(url('favourites.php?type=food'))?>"><?=e(t('Favourite Food'))?></a></nav><?php if(!$saved): ?><div class="panel empty"><h2><?=e(t('Save something you love.'))?></h2><p><?=e(t('Tap the heart on a shop or dish to find it here later.'))?></p><a class="pill primary" href="<?=e(url($type==='shops'?'restaurants.php':'index.php'))?>"><?=e(t('Explore →'))?></a></div><?php else: ?><div class="saved-grid"><?php foreach($saved as $entry): ?>
<?php if($type==='shops'): $available=$entry['status']==='approved'; ?><article class="panel padded saved-shop"><div class="saved-card-head"><img class="business-logo" src="<?=e($available?image_url($entry['logo_id']):url('assets/placeholder.svg'))?>" alt=""><?=favourite_button('shops',(int)$entry['seller_id'],'favourites.php?type=shops',$entry['shop_name'])?></div><h2><?=e($entry['business_name']??$entry['shop_name'])?></h2><p><?=e($entry['address']??t('This shop is currently unavailable.'))?></p><?php if($available): ?><a class="pill" href="<?=e(url('restaurant.php?id='.$entry['store_id']))?>"><?=e(t('View Restaurant →'))?></a><?php else: ?><span class="chip pending"><?=e(t('Currently unavailable'))?></span><?php endif ?></article>
<?php else: $available=$entry['product_id']&&dish_is_live((int)$entry['product_id'])&&$entry['category_active']&&$entry['shop_status']==='approved'; ?><article class="food-card saved-food"><div class="food-image"><img src="<?=e($available?image_url($entry['photo_id']):url('assets/placeholder.svg'))?>" alt="<?=e($entry['name']??$entry['product_name'])?>"><?=favourite_button('food',(int)$entry['product_key'],'favourites.php?type=food',$entry['product_name'])?></div><div class="food-content"><h2><?=e($entry['name']??$entry['product_name'])?></h2><p class="subtitle"><?=e($entry['business_name']??$entry['shop_name'])?></p><?php if($available): ?><div class="price-row"><strong><?=money((int)$entry['price_paisa'])?></strong><form method="post" action="<?=e(url('cart.php'))?>" data-cart-form><?=csrf()?><input type="hidden" name="action" value="add"><input type="hidden" name="id" value="<?=$entry['product_id']?>"><button class="pill primary compact"><?=e(t('＋ Add'))?></button></form></div><?php else: ?><p class="chip pending"><?=e(t('Currently unavailable'))?></p><?php if($entry['store_id']&&$entry['shop_status']==='approved'): ?><a href="<?=e(url('restaurant.php?id='.$entry['store_id']))?>"><?=e(t('View shop →'))?></a><?php endif ?><?php endif ?></div></article><?php endif ?>
<?php endforeach ?></div><?php endif ?></main><?php require ROOT.'/app/footer.php'; ?>
